 plan:{now:["أغلق التطبيق الذي يثير المقارنة الآن","اكتب ثلاث نعم خاصة بك"],week:["حدد وقتًا يوميًا محدودًا لوسائل التواصل","ألغِ متابعة الحسابات التي تشعرك بالنقص"],long:["ضع أهدافك بمعاييرك لا بمعايير الآخرين","تذكر: الناس يعرضون أفضل لحظاتهم فقط"]},
